FUNCTION_BLOCK FB
VAR_INPUT
    enqueue: BOOL;
    dequeue: BOOL;
    reset: BOOL;
    capacity: DINT;
END_VAR

VAR_OUTPUT
    elementCount: DINT := 0;
    status: WORD := 16#0000;
END_VAR

VAR_IN_OUT
    item: DINT;
    buffer: ARRAY[1..4] OF DINT;
END_VAR

VAR
    head: DINT := 1;
    tail: DINT := 1;
    prevEnqueue: BOOL := FALSE;
    prevDequeue: BOOL := FALSE;
END_VAR

// Rising edge detection
enqueueRising := enqueue AND NOT prevEnqueue;
dequeueRising := dequeue AND NOT prevDequeue;

// Update edge history
prevEnqueue := enqueue;
prevDequeue := dequeue;

// Reset (highest priority)
IF reset THEN
    head := 1;
    tail := 1;
    elementCount := 0;
    status := 16#0000;
    RETURN;
END_IF

// Enqueue operation
IF enqueueRising THEN
    IF elementCount >= capacity THEN
        status := 16#8002;
    ELSE
        buffer[tail] := item;
        tail := (tail MOD 4) + 1;
        elementCount := elementCount + 1;
        status := 16#0000;
    END_IF
    RETURN;
END_IF

// Dequeue operation
IF dequeueRising THEN
    IF elementCount = 0 THEN
        status := 16#8001;
    ELSE
        item := buffer[head];
        head := (head MOD 4) + 1;
        elementCount := elementCount - 1;
        status := 16#0000;
    END_IF
    RETURN;
END_IF

// Idle state
status := 16#0000;
END_FUNCTION_BLOCK
